    void expiredCouponIsRejected() {
        CouponException error = assertThrows(CouponException.class,
                () -> Coupons.validate("SUMMER20", CATALOG, LocalDate.of(2026, 6, 1)));
        assertEquals("COUPON_EXPIRED", error.getCode().name());
    }
